style.css:
@-moz-document domain("youtube.com") {
@keyframes yt-2025-thumb-tilt {
  0% { transform: rotate(0deg) scale(1); }
  35% { transform: rotate(-10deg) scale(1); }
  70% { transform: rotate(3deg) scale(1); }
  100% { transform: rotate(0deg) scale(1); }
}

@keyframes yt-2025-subtle-sparks {
  0% {
    opacity: 0.9;
    transform: translate(-50%, -50%) scale(0.6);
    box-shadow: 0 -7px 0 0 rgba(255, 255, 255, 0.85), 6px -4px 0 0 rgba(255, 255, 255, 0.85), 6px 5px 0 0 rgba(255, 255, 255, 0.85), -6px -4px 0 0 rgba(255, 255, 255, 0.85);
  }
  70% {
    opacity: 0.7;
    transform: translate(-50%, -50%) scale(1);
    box-shadow: 0 -13px 0 0 rgba(255, 255, 255, 0.6), 11px -7px 0 0 rgba(255, 255, 255, 0.6), 11px 8px 0 0 rgba(255, 255, 255, 0.6), -11px -7px 0 0 rgba(255, 255, 255, 0.6);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.1);
    box-shadow: 0 -16px 0 -1px transparent, 14px -9px 0 -1px transparent, 14px 10px 0 -1px transparent, -14px -9px 0 -1px transparent;
  }
}

